import{c as a,Q as e,j as s,m as n}from"./chunks/framework.DOi4mjdC.js";const r="/assets/zh-cn_formulaimage_0000002566625829.CyDP3k5E.png",h=JSON.parse('{"title":"SubC","description":"","frontmatter":{},"headers":[{"level":1,"title":"SubC","slug":"subc"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/Reg矢量计算/基础算术/SubC.md","filePath":"api/SIMD-API/基础API/Reg矢量计算/基础算术/SubC.md"}'),d={name:"api/SIMD-API/基础API/Reg矢量计算/基础算术/SubC.md"};function i(l,t,p,c,o,g){return e(),s("div",null,[...t[0]||(t[0]=[n('<h1 id="subc" tabindex="-1">SubC <a class="header-anchor" href="#subc" aria-label="Permalink to &quot;SubC&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>x</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>x</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>根据mask对源操作数srcReg0、srcReg1以及进位数据carrySrc进行按元素相减的操作，将结果写入目的操作数dstReg。srcReg0、srcReg1、carrySrc相减时如果产生借位，在MaskReg carry中对应位置每4bit的最低位写0，否则写1。计算公式如下：</p><p><img src="'+r+`" alt=""></p><p>具体的示例如下：</p><p><strong>表 1</strong> 示例说明</p><table tabindex="0"><thead><tr><th>数据类型</th><th>是否借位</th><th>示例说明</th></tr></thead><tbody><tr><td>int32_t数据类型</td><td>不产生借位</td><td>a_i = 5，b_i = 2, carrySrc_i = 1 dst_i = a_i - b_i - carrySrc_i = 2 carryp中对应位置每4bit的最低位写1：carry_i = 1</td></tr><tr><td>int32_t数据类型</td><td>产生借位</td><td>a_i = 5, b_i = -7, carrySrc_i = 1 dst_i = a_i - b_i - carrySrc_i = 11 carryp中对应位置每4bit的最低位写0：carry_i = 0</td></tr><tr><td>uint32_t数据类型</td><td>不产生借位</td><td>a_i = 5, b_i = 2, carrySrc_i = 1 dst_i = a_i - b_i - carrySrc_i = 2 carryp中对应位置每4bit的最低位写1：carry_i = 1</td></tr><tr><td>uint32_t数据类型</td><td>产生借位</td><td>a_i = 5, b_i = 7, carrySrc_i = 1 dst_i = a_i - b_i - carrySrc_i = -3 carryp中对应位置每4bit的最低位写0：carry_i = 0</td></tr></tbody></table><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T = DefaultType, typename U&gt;</span></span>
<span class="line"><span>__simd_callee__ inline void SubC(MaskReg&amp; carry, U&amp; dstReg, U&amp; srcReg0, U&amp; srcReg1, MaskReg&amp; carrySrc, MaskReg&amp; mask)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 2</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>矢量目的操作数和源操作数的数据类型。 Ascend 950PR/Ascend 950DT，支持的数据类型为：uint32_t/int32_t</td></tr><tr><td>U</td><td>目的操作数的RegTensor类型，例如RegTensor&lt;half&gt;，由编译器自动推导，用户不需要填写。</td></tr></tbody></table><p><strong>表 3</strong> 参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>dstReg</td><td>输出</td><td>目的操作数。 类型为RegTensor。</td></tr><tr><td>srcReg0</td><td>输入</td><td>源操作数。 类型为RegTensor。 数据类型需要与目的操作数保持一致。</td></tr><tr><td>srcReg1</td><td>输入</td><td>源操作数。 类型为RegTensor。 数据类型需要与目的操作数保持一致。</td></tr><tr><td>carrySrc</td><td>输入</td><td>源操作数。输入进位值。 类型为MaskReg。</td></tr><tr><td>carry</td><td>输出</td><td>目的操作数。输出进位值。 类型为MaskReg。</td></tr><tr><td>mask</td><td>输入</td><td>源操作数元素操作的有效指示，详细说明请参考MaskReg。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>无</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T&gt;</span></span>
<span class="line"><span>__simd_vf__ inline void SubC(__ubuf__ T* dst0Addr, __ubuf__ T* dst1Addr, __ubuf__ T* src0Addr, __ubuf__ T* src1Addr, uint32_t count, uint16_t repeatTimes, uint32_t oneRepeatSize){</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    AscendC::Reg::RegTensor&lt;T&gt; srcReg0;</span></span>
<span class="line"><span>    AscendC::Reg::RegTensor&lt;T&gt; srcReg1;</span></span>
<span class="line"><span>    AscendC::Reg::RegTensor&lt;T&gt; dstReg0;</span></span>
<span class="line"><span>    AscendC::Reg::MaskReg mask; </span></span>
<span class="line"><span>    AscendC::Reg::MaskReg maskZero = AscendC::Reg::CreateMask&lt;T, AscendC::Reg::MaskPattern::ALLF&gt;();</span></span>
<span class="line"><span>    AscendC::Reg::MaskReg carry = AscendC::Reg::CreateMask&lt;uint8_t&gt;();</span></span>
<span class="line"><span>    for (uint16_t i = 0; i &lt; repeatTimes; i++) {</span></span>
<span class="line"><span>        mask = AscendC::Reg::UpdateMask&lt;T&gt;(count);</span></span>
<span class="line"><span>        AscendC::Reg::LoadAlign(srcReg0, src0Addr + i * oneRepeatSize);</span></span>
<span class="line"><span>        AscendC::Reg::LoadAlign(srcReg1, src1Addr + i * oneRepeatSize);</span></span>
<span class="line"><span>        AscendC::Reg::SubC(carry, dstReg0, srcReg0, srcReg1, maskZero, mask);</span></span>
<span class="line"><span>        // 8*4B=32B align</span></span>
<span class="line"><span>        AscendC::Reg::StoreAlign&lt;uint32_t, AscendC::Reg::MaskDist::DIST_NORM&gt;((__ubuf__ uint32_t*)dst1Addr + i * 8, carry);</span></span>
<span class="line"><span>        AscendC::Reg::StoreAlign(dst0Addr + i * oneRepeatSize, dstReg0, mask);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div>`,22)])])}const b=a(d,[["render",i]]);export{h as __pageData,b as default};
